PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE daily_progress (
      date TEXT PRIMARY KEY,
      study_minutes INTEGER DEFAULT 0,
      topics_completed INTEGER DEFAULT 0,
      tasks_completed INTEGER DEFAULT 0,
      revisions_completed INTEGER DEFAULT 0,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE user_settings (
      id TEXT PRIMARY KEY DEFAULT 'global',
      theme TEXT DEFAULT 'dark',
      daily_study_goal_hours INTEGER DEFAULT 6,
      show_welcome BOOLEAN DEFAULT TRUE,
      font_size TEXT DEFAULT 'small',
      updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
    , pomodoro_minutes INTEGER DEFAULT 25, break_minutes INTEGER DEFAULT 5);
CREATE TABLE study_sessions (
      id TEXT PRIMARY KEY,
      date TEXT NOT NULL,
      start_time DATETIME NOT NULL,
      end_time DATETIME NOT NULL,
      duration_minutes INTEGER NOT NULL,
      type TEXT NOT NULL,
      title TEXT,
      task_id TEXT,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      FOREIGN KEY (date) REFERENCES daily_progress(date) ON DELETE CASCADE
    );
CREATE TABLE d1_migrations(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE subjects (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  color TEXT,
  icon TEXT,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
, details TEXT);
CREATE TABLE chapters (
  id TEXT PRIMARY KEY,
  subject_id TEXT NOT NULL,
  name TEXT NOT NULL,
  order_index INTEGER NOT NULL,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP, paper TEXT DEFAULT 'Paper 1', tag TEXT, estimated_marks INTEGER,
  FOREIGN KEY (subject_id) REFERENCES subjects(id) ON DELETE CASCADE
);
CREATE TABLE topics (
  id TEXT PRIMARY KEY,
  chapter_id TEXT NOT NULL,
  name TEXT NOT NULL,
  status TEXT DEFAULT 'pending', 
  order_index INTEGER NOT NULL,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, revision_count INTEGER DEFAULT 0, last_revised TEXT, next_revision_due TEXT, completed_at TEXT, notes TEXT, importance TEXT,
  FOREIGN KEY (chapter_id) REFERENCES chapters(id) ON DELETE CASCADE
);
CREATE TABLE subtopics (
  id TEXT PRIMARY KEY,
  topic_id TEXT NOT NULL,
  name TEXT NOT NULL,
  content TEXT,
  status TEXT DEFAULT 'not-started',
  order_index INTEGER NOT NULL,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP, importance TEXT,
  FOREIGN KEY (topic_id) REFERENCES topics(id) ON DELETE CASCADE
);
CREATE TABLE tasks (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  category TEXT NOT NULL, 
  priority TEXT NOT NULL, 
  completed BOOLEAN DEFAULT FALSE,
  due_date TEXT,
  completed_at DATETIME,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
, date TEXT, estimated_minutes INTEGER, actual_minutes INTEGER);
CREATE TABLE activities (
  id TEXT PRIMARY KEY,
  type TEXT NOT NULL,
  description TEXT NOT NULL,
  timestamp DATETIME NOT NULL,
  subject_id TEXT,
  color TEXT,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE study_blocks (
  id TEXT PRIMARY KEY,
  date TEXT NOT NULL, 
  subject_id TEXT NOT NULL,
  topic_id TEXT,
  title TEXT NOT NULL,
  start_time TEXT NOT NULL, 
  end_time TEXT NOT NULL, 
  priority TEXT NOT NULL,
  completed BOOLEAN DEFAULT FALSE,
  notes TEXT,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE exams (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  type TEXT NOT NULL,
  date TEXT NOT NULL,
  subject_ids TEXT NOT NULL,
  completed BOOLEAN DEFAULT 0,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
, topics_description TEXT);
CREATE TABLE stories (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  description TEXT,
  duration_seconds INTEGER,
  mime_type TEXT,
  file_size INTEGER,
  kv_key TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
, type TEXT DEFAULT 'story');
CREATE TABLE IF NOT EXISTS "audio_notes" (
  id TEXT PRIMARY KEY,
  topic_id TEXT NOT NULL,
  duration_seconds REAL NOT NULL,
  mime_type TEXT NOT NULL,
  file_size INTEGER NOT NULL,
  kv_key TEXT NOT NULL,
  sequence_index INTEGER NOT NULL DEFAULT 0,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (topic_id) REFERENCES topics(id) ON DELETE CASCADE
);
CREATE TABLE story_audios (
  id TEXT PRIMARY KEY,
  story_id TEXT NOT NULL,
  duration_seconds REAL NOT NULL,
  mime_type TEXT NOT NULL,
  file_size INTEGER NOT NULL,
  kv_key TEXT NOT NULL,
  sequence_index INTEGER NOT NULL DEFAULT 0,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (story_id) REFERENCES stories(id) ON DELETE CASCADE
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_study_sessions_date ON study_sessions(date);
CREATE INDEX idx_chapters_subject ON chapters(subject_id);
CREATE INDEX idx_topics_chapter ON topics(chapter_id);
CREATE INDEX idx_subtopics_topic ON subtopics(topic_id);
CREATE INDEX idx_study_blocks_date ON study_blocks(date);
CREATE INDEX idx_audio_notes_topic ON audio_notes(topic_id);
CREATE INDEX idx_story_audios_story ON story_audios(story_id);
